                raise KeyError(part)
            val = val[part]
        return val

    def apply_filters(val: Any, filter_names: list[str]) -> str:
        # Design note: None renders as empty string
        s = "" if val is None else str(val)
        for f in filter_names:
            f = f.strip()
            if f == "upper":
                s = s.upper()
            elif f == "lower":
                s = s.lower()
            elif f == "title":
                s = s.title()
            elif f == "trim":
                s = s.strip()
            else:
                raise ValueError(f"Unknown filter: {f}")
        return s

    def replacement_func(match: re.Match) -> str:
        content = match.group(1).strip()
        if not content:
            return ""

        parts = content.split("|")
        path = parts[0].strip()
        filters = parts[1:]

        val = get_value(path, context)
        return apply_filters(val, filters)

    # This regex matches everything between {{ and }}
    pattern = r"{{\s*(.*?)\s*}}"
    return re.sub(pattern, replacement_func, template)
